  'Solo puede haber un modo de configuración activo. Cambiar de modo modifica qué selección de modelos utiliza Nodus, no solo la vista de este formulario.':
    'Un seul mode de configuration peut être actif. Changer de mode modifie la sélection de modèles utilisée par Nodus, pas seulement l\'affichage de ce formulaire.',
  'Selección de modelos': 'Sélection des modèles',
  'Configuración básica': 'Configuration de base',
  'Configuración avanzada': 'Configuration avancée',
  '¿Cambiar a la configuración básica?': 'Passer à la configuration de base ?',
  '¿Cambiar a la configuración avanzada?': 'Passer à la configuration avancée ?',
  'Solo un modo puede estar activo. El modelo general pasará a utilizarse en las tareas de texto y las selecciones avanzadas dejarán de aplicarse.':
    'Un seul mode peut être actif. Le modèle général sera désormais utilisé pour les tâches de texte et les sélections avancées ne s\'appliqueront plus.',
  'Después del cambio, revisa y completa «Modelo general de texto» antes de utilizar las funciones de IA. Una configuración incompleta puede hacer que esas funciones fallen.':
    'Après le changement, vérifiez et complétez « Modèle général de texte » avant d\'utiliser les fonctions d\'IA. Une configuration incomplète peut entraîner l\'échec de ces fonctions.',
  'Solo un modo puede estar activo. Cada tarea pasará a utilizar el modelo seleccionado en su propio campo en lugar de depender únicamente del modelo general.':
    'Un seul mode peut être actif. Chaque tâche utilisera désormais le modèle sélectionné dans son propre champ au lieu de dépendre uniquement du modèle général.',
  'Después del cambio, revisa y completa los modelos de «Ajustes avanzados comunes» y del vault actual. Una tarea sin un modelo válido puede fallar.':
    'Après le changement, vérifiez et complétez les modèles des « Paramètres avancés communs » et de l\'espace actuel. Une tâche sans modèle valide peut échouer.',
  'Cambiar a configuración básica': 'Passer à la configuration de base',
  'Cambiar a configuración avanzada': 'Passer à la configuration avancée',
  'Acerca de Nodus Research': 'À propos de Nodus Research',
  'Nodus es un proyecto independiente de código abierto, desarrollado y mantenido principalmente por una sola persona. No es un servicio comercial ni un producto de pago: la aplicación seguirá siendo gratuita y su código permanecerá abierto.':
    'Nodus est un projet indépendant open source, développé et maintenu principalement par une seule personne. Ce n\'est pas un service commercial ni un produit payant : l\'application restera gratuite et son code restera ouvert.',
  'Si Nodus te ayuda a estudiar, investigar o escribir y quieres contribuir voluntariamente a su desarrollo, puedes apoyar el proyecto mediante PayPal o Ko-fi. La donación es completamente opcional: no desbloquea funciones ni cambia el acceso a la aplicación.':
    'Si Nodus vous aide à étudier, faire de la recherche ou écrire et que vous souhaitez contribuer volontairement à son développement, vous pouvez soutenir le projet via PayPal ou Ko-fi. Le don est entièrement facultatif : il ne débloque aucune fonctionnalité et ne modifie pas l\'accès à l\'application.',
  'Apoyar con PayPal': 'Soutenir via PayPal',
  'Apoyar con Ko-fi': 'Soutenir via Ko-fi',
  'Apoyar': 'Soutenir',
