  'Sin conectar': 'Non connecté',
  'Borrar conexión con ChatGPT': 'Supprimer la connexion à ChatGPT',
  'Nodus eliminará de este equipo el ID del túnel y la clave de ejecución guardada. Podrás configurarlos otra vez cuando quieras.':
    'Nodus supprimera de cet appareil l\'identifiant du tunnel et la clé d\'exécution enregistrée. Vous pourrez les reconfigurer à tout moment.',
  'Borrar conexión': 'Supprimer la connexion',
  'Conectar Nodus': 'Connecter Nodus',
  'Conecta Nodus': 'Connectez Nodus',
  'Usa tus contenidos de Nodus desde tu asistente preferido.': 'Utilisez le contenu de Nodus depuis votre assistant préféré.',
  'Otro cliente': 'Autre client',
  'Conectado a ChatGPT': 'Connecté à ChatGPT',
  'Túnel seguro de OpenAI': 'Tunnel sécurisé OpenAI',
  'Conecta ChatGPT sin publicar tu servidor ni abrir puertos. Nodus usa el túnel seguro oficial de OpenAI.':
    'Connectez ChatGPT sans publier votre serveur ni ouvrir de ports. Nodus utilise le tunnel sécurisé officiel d\'OpenAI.',
  'Último paso: añade Nodus en ChatGPT': 'Dernière étape : ajoutez Nodus dans ChatGPT',
  'Abre la configuración de ChatGPT, crea una app, elige «Tunnel» como conexión y selecciona el túnel que acabas de configurar.':
    'Ouvrez les paramètres de ChatGPT, créez une app, choisissez « Tunnel » comme connexion et sélectionnez le tunnel que vous venez de configurer.',
  'Activa el modo desarrollador si es necesario': 'Activez le mode développeur si nécessaire',
  'En ChatGPT, ve a Configuración → Seguridad e inicio de sesión y activa Modo desarrollador. Si ya está activo, continúa con el siguiente paso.':
    'Dans ChatGPT, accédez à Paramètres → Sécurité et connexion et activez le mode développeur. S’il est déjà activé, passez à l’étape suivante.',
  'Abre el configurador de complementos': 'Ouvrez le configurateur de plugins',
  'En la configuración de ChatGPT, abre Complementos, pulsa Añadir complemento e introduce un nombre, por ejemplo «Nodus».':
    'Dans les paramètres de ChatGPT, ouvrez Plugins, sélectionnez Ajouter un plugin et saisissez un nom, par exemple « Nodus ».',
  'Selecciona el túnel de Nodus': 'Sélectionnez le tunnel Nodus',
  'Cuando ChatGPT solicite la conexión, elige Túnel y selecciona el túnel que acabas de configurar; no introduzcas la URL local.':
    'Lorsque ChatGPT demande la connexion, choisissez Tunnel et sélectionnez le tunnel que vous venez de configurer ; ne saisissez pas l’URL locale.',
  'Configura la autenticación': 'Configurez l’authentification',
  'En Autenticación, selecciona Sin autenticación. No pegues aquí la clave de ejecución de OpenAI ni el token MCP local.':
    'Dans Authentification, choisissez Aucune authentification. Ne collez ici ni la clé d’exécution OpenAI ni le jeton MCP local.',
  'Confirma y termina': 'Confirmez et terminez',
  'Marca Entiendo y quiero continuar y guarda el complemento. Nodus estará disponible en los chats donde actives el complemento.':
    'Cochez Je comprends et je souhaite continuer, puis enregistrez le plugin. Nodus sera disponible dans les chats où vous activez le plugin.',
  'Abrir configuración de ChatGPT': 'Ouvrir les paramètres de ChatGPT',
  'Abrir diagnóstico': 'Ouvrir le diagnostic',
  'Desconectar': 'Déconnecter',
  'Crea un túnel en OpenAI': 'Créez un tunnel dans OpenAI',
  'Abre la página de túneles, pulsa Create y copia el identificador que empieza por tunnel_.':
    'Ouvrez la page des tunnels, cliquez sur Create et copiez l\'identifiant qui commence par tunnel_.',
  'Abrir túneles de OpenAI': 'Ouvrir les tunnels OpenAI',
  'ID del túnel': 'Identifiant du tunnel',
  'Crea una clave de ejecución': 'Créez une clé d\'exécution',
  'La clave necesita permisos Tunnels Read + Use. Nodus la guarda en el almacén protegido de este dispositivo y nunca vuelve a mostrarla.':
    'La clé nécessite les autorisations Tunnels Read + Use. Nodus la conserve dans le stockage protégé de cet appareil et ne l\'affiche plus jamais.',
  'Crear clave de ejecución': 'Créer une clé d\'exécution',
  'Clave de ejecución': 'Clé d\'exécution',
  'Ya hay una clave guardada; déjalo vacío para conservarla.': 'Une clé est déjà enregistrée ; laissez ce champ vide pour la conserver.',
  'Pega aquí la clave nueva': 'Collez la nouvelle clé ici',
  'Nodus activará MCP, descargará y verificará el cliente oficial y mantendrá la conexión mientras la aplicación esté abierta.':
    'Nodus activera MCP, téléchargera et vérifiera le client officiel, puis maintiendra la connexion tant que l\'application est ouverte.',
  'Volver a conectar': 'Reconnecter',
  'Conectar con ChatGPT': 'Connecter à ChatGPT',
  'Ver detalle técnico': 'Voir les détails techniques',
  'Cuando uses Nodus desde ChatGPT, OpenAI recibirá las consultas y los resultados que ChatGPT solicite. Las bóvedas permanecen en este equipo y el servidor local no se publica en Internet.':
    'Lorsque vous utilisez Nodus depuis ChatGPT, OpenAI reçoit les requêtes et les résultats demandés par ChatGPT. Vos espaces restent sur cet appareil et le serveur local n\'est pas publié sur Internet.',
  'Borrar conexión guardada': 'Supprimer la connexion enregistrée',
  'Claude Desktop puede conectar directamente con el servidor local de Nodus mediante este puente stdio:':
    'Claude Desktop peut se connecter directement au serveur local de Nodus au moyen de ce pont stdio :',
  'Copia esta configuración en Claude Desktop y reinicia la aplicación.': 'Copiez cette configuration dans Claude Desktop, puis redémarrez l\'application.',
  'Usa Streamable HTTP con la URL local y la cabecera bearer siguientes.': 'Utilisez Streamable HTTP avec l\'URL locale et l\'en-tête bearer suivants.',
  'El ID debe empezar por tunnel_ y contener los 32 caracteres que muestra OpenAI.': 'L\'identifiant doit commencer par tunnel_ et contenir les 32 caractères affichés par OpenAI.',
  'Falta la clave de ejecución de OpenAI.': 'La clé d\'exécution OpenAI est manquante.',
  'OpenAI todavía no ofrece el cliente de túnel para este sistema.': 'OpenAI ne propose pas encore le client de tunnel pour ce système.',
  'No se pudo descargar el cliente oficial. Comprueba la conexión a Internet e inténtalo de nuevo.': 'Impossible de télécharger le client officiel. Vérifiez votre connexion Internet et réessayez.',
  'La descarga no superó la comprobación de seguridad y no se ha ejecutado.': 'Le téléchargement a échoué au contrôle de sécurité et n\'a pas été exécuté.',
  'OpenAI rechazó la clave. Crea una clave de ejecución nueva y vuelve a pegarla.': 'OpenAI a refusé la clé. Créez une nouvelle clé d\'exécution et collez-la à nouveau.',
  'Tu cuenta necesita permisos Tunnels Read + Use en la organización de OpenAI.': 'Votre compte doit disposer des autorisations Tunnels Read + Use dans l\'organisation OpenAI.',
  'OpenAI no encuentra ese túnel en la organización asociada a la clave.': 'OpenAI ne trouve pas ce tunnel dans l\'organisation associée à la clé.',
  'No se puede alcanzar OpenAI. Revisa la conexión, el proxy o el cortafuegos.': 'OpenAI est inaccessible. Vérifiez la connexion, le proxy ou le pare-feu.',
  'Nodus no pudo conectar el túnel con su servidor MCP local.': 'Nodus n\'a pas pu connecter le tunnel à son serveur MCP local.',
  'El cliente del túnel se detuvo. Pulsa Volver a conectar.': 'Le client du tunnel s\'est arrêté. Cliquez sur Reconnecter.',
  'No se pudo completar la conexión. Abre el detalle técnico o inténtalo de nuevo.': 'La connexion n\'a pas pu être établie. Ouvrez les détails techniques ou réessayez.',
  'Conectado mediante el túnel seguro de OpenAI.': 'Connecté via le tunnel sécurisé OpenAI.',
