  'Exportar (.nodus)': 'Exporter (.nodus)',
  'Importar (.nodus)': 'Importer (.nodus)',
  'La copia incluye todos los datos de Nodus: textos extraídos, embeddings de ideas, resúmenes y pasajes, modelos seleccionados, grafo, ajustes y claves API, dentro de un archivo cifrado.':
    'La sauvegarde chiffrée contient toutes les données de Nodus : textes extraits, embeddings des idées, résumés et passages, modèles sélectionnés, graphe, paramètres et clés API.',
  'IA avanzada': 'IA avancée',
  'Modelo de extracción (extrae temas, ideas, evidencias y huecos)': 'Modèle d\'extraction (extrait les thèmes, idées, preuves et lacunes)',
  'Modelo de síntesis/tutor (asistente de investigación y narrativa del tutor)': 'Modèle de synthèse/tuteur (assistant de recherche et narration du tuteur)',
  'Modelo de fusión (deduplica y relaciona ideas; muchas llamadas pequeñas, conviene uno rápido)':
    'Modèle de fusion (déduplique et relie les idées ; nombreux petits appels, un modèle rapide est préférable)',
  'Modelo de embeddings (similitud semántica multilingüe)': 'Modèle d\'embeddings (similarité sémantique multilingue)',
  'Indexación de embeddings': 'Indexation des embeddings',
  'Genera embeddings solo para ideas que aún no los tienen.': 'Génère des embeddings uniquement pour les idées qui n\'en ont pas encore.',
  'Indexar pendientes': 'Indexer les éléments en attente',
  'Borra todos los embeddings y los regenera desde cero. Útil tras cambiar de modelo.':
    'Supprime tous les embeddings et les régénère depuis zéro. Utile après un changement de modèle.',
  'Reindexar todo': 'Tout réindexer',
  'Llamadas simultáneas': 'Appels simultanés',
  'Razonamiento (chat/tutor/escritura)': 'Raisonnement (chat/tuteur/écriture)',
  'Los escaneos van sin razonamiento para ir más rápido; esto solo afecta a las respuestas conversacionales. En Codex, el nivel que fijes a cada tarea en Modelos manda también en sus escaneos.': 'Les analyses tournent sans raisonnement pour aller plus vite ; cela ne concerne que les réponses conversationnelles. Sur Codex, le niveau fixé pour une tâche dans Modèles gouverne aussi ses analyses.',
  'Desactivado (más rápido)': 'Désactivé (plus rapide)',
  'Bajo': 'Bas',
  'Medio': 'Moyen',
  'Alto (más lento)': 'Élevé (plus lent)',
  'OpenRouter: priorizar velocidad': 'OpenRouter : prioriser la vitesse',
  'Enruta hacia el proveedor más rápido disponible. Puede aumentar ligeramente el coste.':
    'Achemine vers le fournisseur disponible le plus rapide. Peut légèrement augmenter le coût.',
  'Razonamiento': 'Raisonnement',
  'Modelo de razonamiento: más lento para escanear.': 'Modèle de raisonnement : plus lent pour l\'analyse.',
