  'storage no configurado': 'stockage non configuré',
  'La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.':
    'La synchronisation peut fonctionner, mais Nodus a besoin d\'un modèle par défaut pour extraire les thèmes, les idées et les preuves.',
  'Sincroniza Zotero para crear el corpus': 'Synchroniser Zotero pour créer le corpus',
