  'Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones.':
    'Enchaîne thèmes, idées, résumé, indexation (idées et passages) et découverte de relations.',
  'Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones para toda la biblioteca filtrada.':
    'Enchaîne thèmes, idées, résumé, indexation (idées et passages) et découverte de relations pour toute la bibliothèque filtrée.',
  'Procesar todo encadena para las {n} obra(s) filtrada(s): temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones. Es una operación larga que consume tokens del modelo seleccionado. ¿Continuar?':
    'Tout traiter enchaîne, pour les {n} œuvre(s) filtrée(s) : thèmes, idées, résumé, indexation (idées et passages) et découverte de relations. C\'est une opération longue qui consomme des tokens du modèle sélectionné. Continuer ?',
  'Procesado completo en cola para {n} obra(s). Verás el progreso en la cola.':
    'Traitement complet mis en file d\'attente pour {n} œuvre(s). Vous verrez la progression dans la file.',
  'Después elige Temas, Ideas o Ambos.': 'Ensuite, choisissez Thèmes, Idées ou Les deux.',
