  'Reconstruye los temas padre de toda la biblioteca con análisis ligero. Útil tras cambiar criterios temáticos.':
    'Reconstruit les thèmes parents de toute la bibliothèque avec une analyse légère. Utile après avoir changé les critères thématiques.',
  'Reasignar': 'Réassigner',
  'Genera embeddings para las ideas que aún no los tienen. No regenera los existentes.':
    'Génère des embeddings pour les idées qui n\'en ont pas encore. Ne régénère pas ceux qui existent déjà.',
  'Borra todos los embeddings y los regenera desde cero. Útil tras cambiar de modelo de embeddings.':
    'Supprime tous les embeddings et les régénère depuis zéro. Utile après avoir changé de modèle d\'embeddings.',
  'Descubrir relaciones': 'Découvrir des relations',
  'Usa embeddings e IA para validar puentes semánticos entre ideas que aún no están conectadas. El progreso se muestra en la cola.':
    'Utilise les embeddings et l\'IA pour valider des ponts sémantiques entre idées pas encore connectées. La progression s\'affiche dans la file.',
  'Descubrir': 'Découvrir',
  'Colección': 'Collection',
  'Filtrar por colección': 'Filtrer par collection',
  'Sincroniza para poder filtrar por colección.': 'Synchronisez pour pouvoir filtrer par collection.',
  'Buscar colección…': 'Rechercher une collection…',
  'Combinar colecciones': 'Combiner les collections',
  'Aún no hay colecciones. Pulsa “Sincronizar” para leer la estructura de colecciones de Zotero.':
    'Aucune collection pour le moment. Cliquez sur “Synchroniser” pour lire la structure des collections de Zotero.',
  'No hay colecciones que coincidan.': 'Aucune collection ne correspond.',
  'Colecciones:': 'Collections :',
  'Buscar y fusionar duplicados': 'Rechercher et fusionner les doublons',
  'Detecta obras repetidas (mismo DOI, o mismo título, año y autores) y te deja revisarlas y fusionarlas conservando una sola copia. La misma obra en varias colecciones de Zotero no se duplica.':
    'Détecte les œuvres répétées (même DOI, ou même titre, année et auteurs) et vous permet de les examiner et de les fusionner en ne conservant qu\'une seule copie. La même œuvre dans plusieurs collections Zotero n\'est pas dupliquée.',
  'Revisar duplicados': 'Vérifier les doublons',
  'Duplicados en la biblioteca': 'Doublons dans la bibliothèque',
  'Buscando duplicados…': 'Recherche de doublons…',
  'No se han encontrado duplicados.': 'Aucun doublon trouvé.',
  '{g} grupo(s) · {n} obra(s) duplicadas a fusionar': '{g} groupe(s) · {n} œuvre(s) en double à fusionner',
  'Fusionar todos': 'Tout fusionner',
  'La misma obra en varias colecciones de Zotero no se duplica.': 'La même œuvre dans plusieurs collections Zotero n\'est pas dupliquée.',
  'Mismo DOI': 'Même DOI',
  'Mismos metadatos': 'Mêmes métadonnées',
  '{n} copias': '{n} copies',
  'Fusionar': 'Fusionner',
  'Se conserva': 'Conservé',
  '(sin título)': '(sans titre)',
  '{n} idea(s)': '{n} idée(s)',
  'Fusionar todos los duplicados': 'Fusionner tous les doublons',
  'Se fusionarán {g} grupo(s), conservando en cada uno la copia marcada y reasignando sus ideas, evidencia y etiquetas. Las {n} copias sobrantes se eliminarán de la biblioteca de Nodus (Zotero no se modifica). ¿Continuar?':
    '{g} groupe(s) seront fusionnés, en conservant dans chacun la copie marquée et en réassignant ses idées, preuves et étiquettes. Les {n} copies excédentaires seront supprimées de la bibliothèque Nodus (Zotero n\'est pas modifié). Continuer ?',
  'Duplicados': 'Doublons',
  'Buscar y fusionar ideas duplicadas para limpiar el grafo y el listado': 'Rechercher et fusionner les idées en double pour nettoyer le graphe et la liste',
  'Ideas duplicadas': 'Idées en double',
  'Buscando ideas duplicadas…': 'Recherche d\'idées en double…',
  'No se han encontrado ideas duplicadas.': 'Aucune idée en double trouvée.',
  '{g} grupo(s) · {n} idea(s) duplicadas a fusionar': '{g} groupe(s) · {n} idée(s) en double à fusionner',
  'Solo se agrupan ideas con la misma etiqueta y el mismo tipo. La evidencia se conserva íntegra al fusionar.':
    'Seules les idées ayant la même étiquette et le même type sont regroupées. Les preuves sont intégralement conservées lors de la fusion.',
  'Misma etiqueta': 'Même étiquette',
  'Copia de seguridad creada antes de fusionar:': 'Sauvegarde créée avant la fusion :',
  '{n} evidencia(s)': '{n} preuve(s)',
  'Fusionar todas las ideas duplicadas': 'Fusionner toutes les idées en double',
  'Se hará primero una copia de seguridad completa de la base de datos. Después se fusionarán {g} grupo(s), conservando en cada uno la idea marcada y reasignándole toda la evidencia, ocurrencias, temas y conexiones del grafo de las {n} copias sobrantes, que se eliminarán. La evidencia no se pierde. ¿Continuar?':
    'Une sauvegarde complète de la base de données sera d\'abord effectuée. Ensuite, {g} groupe(s) seront fusionnés, en conservant dans chacun l\'idée marquée et en lui réassignant toutes les preuves, occurrences, thèmes et connexions du graphe des {n} copies excédentaires, qui seront supprimées. Aucune preuve n\'est perdue. Continuer ?',
  'Seleccionar los {n} resultados filtrados': 'Sélectionner les {n} résultats filtrés',
