  'No se encontraron nuevas sugerencias verificables para este capítulo.': 'Aucune nouvelle suggestion vérifiable trouvée pour ce chapitre.',
  'Define el objetivo, el alcance, la pregunta principal y el criterio de selección de fuentes. Este texto aparece en la cabecera del proyecto, se envía como contexto a la IA al generar sugerencias y se incluye en la exportación.':
    'Définissez l\'objectif, la portée, la question principale et le critère de sélection des sources. Ce texte apparaît dans l\'en-tête du projet, est envoyé comme contexte à l\'IA lors de la génération de suggestions et est inclus dans l\'export.',
  'Vincula tu pregunta de investigación con el corpus: indica qué áreas ya están cubiertas y qué falta por explorar. Marcar este paso como en curso activa la sección de cobertura en el proyecto.':
    'Reliez votre question de recherche au corpus : indiquez quelles zones sont déjà couvertes et ce qu\'il reste à explorer. Marquer cette étape comme en cours active la section de couverture dans le projet.',
  'Añade obras, ideas, notas, huecos, debates y borradores al proyecto. Estos materiales son los que la IA usará para proponer inserciones con citas verificables en el manuscrito.':
    'Ajoutez des œuvres, idées, notes, lacunes, débats et brouillons au projet. Ce sont ces matériaux que l\'IA utilisera pour proposer des insertions avec des citations vérifiables dans le manuscrit.',
  'Organiza los debates, huecos y borradores que estructurarán el argumento antes de redactar los capítulos. Puedes activar cada bloque por separado para marcar que está listo para usarse.':
    'Organisez les débats, lacunes et brouillons qui structureront l\'argumentation avant de rédiger les chapitres. Vous pouvez activer chaque bloc séparément pour indiquer qu\'il est prêt à l\'emploi.',
  'Importa un capítulo o artículo como texto editable. Nodus lo versiona automáticamente y permite aplicar sugerencias sobre el borrador.':
    'Importez un chapitre ou un article sous forme de texte modifiable. Nodus le versionne automatiquement et permet d\'appliquer des suggestions au brouillon.',
  'Genera sugerencias verificables contra el corpus y revisa las citas del manuscrito antes de exportar o cerrar el proyecto.':
    'Générez des suggestions vérifiables à partir du corpus et vérifiez les citations du manuscrit avant d\'exporter ou de clôturer le projet.',
