  'Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.':
    'Réanalyse mise en file pour {n} œuvre(s) « abstract seul ». Vous verrez la progression dans la file.',
  'Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?':
    'Réanalyse les œuvres qui n\'ont été analysées qu\'avec l\'abstract (le PDF/EPUB n\'était pas disponible lors de leur analyse). Celles dont le texte est désormais disponible dans Zotero retrouveront l\'analyse complète ; les autres sont ignorées sans coût. Continuer ?',
  'Reanalizar': 'Réanalyser',
