  'Falta la clave del proveedor de IA: configúrala en Ajustes': 'La clé du fournisseur d\'IA est manquante : configurez-la dans Paramètres',
  'Profundiza: informe Deep Research del tema': 'Approfondissez : rapport Deep Research sur le sujet',
  'Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.':
    'Maintenant que vous maîtrisez le sujet, générez le rapport académique de plusieurs pages avec toutes les sources citées. Il est enregistré dans Deep Research afin que vous puissiez l\'exporter ou le citer dans votre écriture.',
  'Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.':
    'Vous pouvez changer de section : le rapport continuera à se générer et affichera sa progression à votre retour.',
  'Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.':
    'Dossier enregistré : «{t}» · {s} sections · ~{p} pages. Retrouvez-le dans Deep Research → rapports enregistrés.',
