  'Demo de bases de datos': 'Démo des bases de données',
  'Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.':
    'Trois tableaux de recherche avec tous les types de colonnes, des relations, des enregistrements, des analyses, une conversation et des notes d\'exemple. Comprend un tutoriel guidé.',
  'Cargar demo de bases de datos': 'Charger la démo des bases de données',
  'Cargar datos de ejemplo': 'Charger des données d\'exemple',
  'Tutorial de bases de datos': 'Tutoriel des bases de données',
  'La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.':
    'La liste des bases de données, le tableau à colonnes typées, l\'édition des cellules et les sections d\'analyse et de chat.',
  'Se mostrará el tutorial de bases de datos.': 'Le tutoriel des bases de données va s\'afficher.',
  'Bienvenido al modo bases de datos': 'Bienvenue dans le mode bases de données',
  'Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.':
    'Voici le mode bases de données de Nodus : un gestionnaire de tableaux façon Notion, intégré à votre application. Je vous en montre les éléments en une minute avec trois bases de données d\'exemple déjà chargées. Vous pouvez quitter à tout moment et revoir le tutoriel depuis Paramètres.',
  'Tus bases de datos': 'Vos bases de données',
  'En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.':
    'Toutes vos bases de données apparaissent dans la barre latérale. Chacune possède un identifiant unique généré automatiquement. Cliquez sur l\'une d\'elles pour l\'ouvrir, ou sur le bouton + pour en créer une nouvelle. Les sections Analyse et Chat se trouvent également ici, en bas.',
  'La tabla': 'Le tableau',
  'Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.':
    'Chaque base de données est un tableau à colonnes typées : titre, texte, nombre, date, heure, sélection, sélection multiple et case à cocher. En haut, vous voyez le nombre total d\'entrées et leur pourcentage par rapport à l\'ensemble de vos bases de données.',
  'Edita directamente': 'Modifiez directement',
  'Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.':
    'Cliquez sur n\'importe quelle cellule pour la modifier instantanément. Les colonnes de sélection affichent des options colorées que vous pouvez ajouter à la volée ; les cases à cocher se cochent d\'un clic. Survolez une ligne pour la supprimer.',
  'Columnas a tu medida': 'Des colonnes à votre mesure',
  'Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.':
    'Cliquez sur l\'en-tête d\'une colonne pour la renommer, changer son type ou gérer ses options, et utilisez le bouton + à la fin de l\'en-tête pour ajouter de nouvelles colonnes. « Nouvelle ligne » permet d\'ajouter des enregistrements.',
  'Análisis (próximamente)': 'Analyse (bientôt disponible)',
  'Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.':
    'Vous pourrez ici choisir une base de données et obtenir des statistiques automatiques ainsi qu\'un rapport généré par IA, avec des graphiques et le calcul visible pour rester reproductible. Arrive dans une prochaine phase.',
  'Chat de datos (próximamente)': 'Chat de données (bientôt disponible)',
  'Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.':
    'Un chat conçu pour dialoguer avec une ou plusieurs de vos bases de données, capable de générer des graphiques et des requêtes reproductibles. Arrive également dans une prochaine phase.',
  'Listo para tus datos': 'Prêt pour vos données',
  'Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.':
    'Ceci est une démonstration avec des données d\'exemple. Quand vous voudrez commencer avec les vôtres, créez une base de données depuis la barre latérale et ajoutez vos colonnes. Vous pourrez bientôt aussi importer des CSV et envoyer des fichiers en masse.',
