  'Detalles y fuente': 'Détails et source',
  'Verificar ideas extraídas': 'Vérifier les idées extraites',
  'Cada idea aparece con su tipo (afirmación, hallazgo, constructo, método o marco), la obra de la que procede y la cita textual que la sostiene. Abre el detalle para comprobar si la lectura automática coincide con la tuya.':
    'Chaque idée apparaît avec son type (affirmation, résultat, construit, méthode ou cadre), l\'œuvre dont elle provient et la citation textuelle qui la soutient. Ouvrez la vue détaillée pour vérifier si la lecture automatique correspond à la vôtre.',
  'Busca por palabras clave a través de ideas, obras, huecos, temas, autores y notas. Los resultados te llevan directamente al detalle correspondiente en cada vista.':
    'Recherchez par mots-clés parmi les idées, œuvres, lacunes, thèmes, auteurs et notes. Les résultats vous mènent directement au détail correspondant dans chaque vue.',
  'Tu espacio de notas': 'Votre espace de notes',
  'Crea carpetas y notas en Markdown. Captura respuestas del asistente, borradores del taller de escritura, síntesis de debates e ideas individuales. Las citas internas (nodus://) permanecen clicables.':
    'Créez des dossiers et des notes en Markdown. Capturez les réponses de l\'assistant, les brouillons de l\'atelier d\'écriture, les synthèses de débats et les idées individuelles. Les citations internes (nodus://) restent cliquables.',
  'Debates: la estructura de una contradicción': 'Débats : la structure d\'une contradiction',
  'Cada relación de contradicción o refutación se despliega como un debate de dos bandos con sus autores, evidencias y cronología. Pides una síntesis al modelo para entender la tensión y decides cómo tu trabajo puede resolverla o aprovecharla.':
    'Chaque relation de contradiction ou de réfutation se déploie comme un débat à deux camps avec leurs auteurs, preuves et chronologie. Vous demandez une synthèse au modèle pour comprendre la tension, puis décidez comment votre travail peut la résoudre ou en tirer parti.',
  'Mapa de cobertura: tu pregunta descompuesta': 'Carte de couverture : votre question décomposée',
  'Escribe tu pregunta de investigación y Nodus la desglosa en subpreguntas. Después mapea cuáles cubre tu corpus, cuáles parcialmente y cuáles quedan sin literatura. Es la herramienta para convertir una intuición vaga en un plan de búsqueda estructurado.':
    'Écrivez votre question de recherche et Nodus la décompose en sous-questions. Il cartographie ensuite celles que votre corpus couvre, celles qu\'il couvre seulement partiellement et celles qui restent sans littérature. C\'est l\'outil pour transformer une intuition vague en un plan de recherche structuré.',
  'Notas: tu cuaderno de investigación': 'Notes : votre carnet de recherche',
  'A lo largo del proceso habrás generado hallazgos en el asistente, borradores en el taller y síntesis de debates. Las Notas te permiten organizar todo ello en carpetas jerárquicas — piensa en capítulos y secciones — con un editor Markdown que conserva las citas clicables. Las ideas manuales que crees aquí se integran directamente en el grafo.':
    'Tout au long du processus, vous aurez généré des résultats dans l\'assistant, des brouillons dans l\'atelier et des synthèses de débats. Les Notes vous permettent d\'organiser tout cela en dossiers hiérarchiques — pensez chapitres et sections — avec un éditeur Markdown qui conserve les citations cliquables. Les idées manuelles que vous créez ici s\'intègrent directement dans le graphe.',
  'Inicio resume el estado de tu corpus, los análisis pendientes y el siguiente paso recomendado. La investigación es iterativa: escaneas más obras, vuelven a aparecer ideas y huecos, refinas la ruta y el borrador. Vuelve aquí entre vueltas. Puedes relanzar este recorrido desde Ajustes → Ayuda.':
    'Accueil résume l\'état de votre corpus, les analyses en attente et la prochaine étape recommandée. La recherche est itérative : vous scannez d\'autres œuvres, des idées et des lacunes réapparaissent, vous affinez la trajectoire et le brouillon. Revenez ici entre les tours. Vous pouvez relancer cette visite depuis Paramètres → Aide.',
  'RECUPERACIÓN ACTIVADA': 'RÉCUPÉRATION ACTIVÉE',
  'Tus datos ya están protegidos': 'Vos données sont désormais protégées',
