  'Clave de recuperación independiente': 'Clé de récupération indépendante',
  'Permite recuperar tus copias aunque olvides la contraseña.': 'Permet de restaurer vos sauvegardes même si vous oubliez le mot de passe.',
  'Copiar clave': 'Copier la clé',
  'Guarda el kit fuera de este dispositivo. Podrás restaurar con la contraseña o con la clave de recuperación.':
    'Conservez le kit en dehors de cet appareil. Vous pourrez restaurer avec le mot de passe ou avec la clé de récupération.',
  'Continuar a Nodus': 'Continuer vers Nodus',
  'PROTECCIÓN DE DATOS': 'PROTECTION DES DONNÉES',
  'Hemos detectado una instalación anterior': 'Nous avons détecté une installation précédente',
  'Elige dónde proteger Nodus': 'Choisissez où protéger Nodus',
  'Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.':
    'Vos espaces actuels ne seront ni déplacés ni modifiés. Nous créerons une première sauvegarde chiffrée et vérifiée avant d\'activer la récupération.',
  'Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.':
    'Configurez un dossier sécurisé avant de commencer. Vos espaces continueront de fonctionner localement et Nodus y enregistrera des sauvegardes restaurables.',
  'La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.':
    'La base de données active n\'est jamais ouverte directement depuis Google Drive ou Dropbox : cela évite les conflits et la corruption.',
