  "Elige una presentación de la lista para ver sus diapositivas, o importa un PDF nuevo.": "Choisissez une présentation dans la liste pour voir ses diapositives, ou importez un nouveau PDF.",
  "Eliminar presentación": "Supprimer la présentation",
  "¿Seguro que quieres eliminar «{name}»? Esta acción no se puede deshacer.": "Voulez-vous vraiment supprimer « {name} » ? Cette action est irréversible.",
