  'Chat de Nodus dentro de Zotero: pregunta sobre el ítem abierto con el contexto de tu biblioteca (resumen, ideas, conexiones). Instala el plugin en Zotero; se conecta a Nodus automáticamente.': 'Discutez avec Nodus dans Zotero : posez vos questions sur le document ouvert avec votre bibliothèque comme contexte (résumé, idées, connexions). Installez le plugin dans Zotero ; il se connecte à Nodus automatiquement.',
