  'Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.': 'Un texte court et stable ajouté à TOUTES les images que vous générez de ce personnage. C’est ce qui le fait se ressembler d’une image à l’autre : mieux vaut le modifier le moins possible.',
  'p. ej. «semielfo de rasgos afilados, pelo negro recogido, ojos ámbar»': 'p. ex. « demi-elfe aux traits anguleux, cheveux noirs attachés, yeux ambre »',
