  'Tu mundo': 'Votre monde',
  'Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.': 'Construisez un monde de fiction pièce par pièce. Commencez par les personnages : leurs noms et alias, les faits de leur vie, leurs liens et leur description, avec des portraits et des biographies que vous pouvez générer quand cela vous sert.',
