  '¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.': 'Supprimer cette scène ? Les personnages qui y apparaissent ne sont PAS supprimés.',
  'El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.': 'L’année, c’est quand cela se passe dans le monde ; l’ordre, c’est la place dans le récit. Un prologue situé des siècles plus tôt vient en premier dans le récit et en dernier dans la chronologie.',
