  'Revelado': 'Révélé',
  'Además sabe': 'Sait aussi',
  'Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.': 'Concevez des unités pour l’enseignant ou des notes à distribuer aux élèves, toujours à partir de vos sources.',
  'Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.': 'Choisissez entre une planification pour donner la leçon et des notes prêtes à distribuer.',
  'Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.': 'Choisissez entre des notes pour apprendre et une planification pour enseigner le sujet.',
  'Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.': 'Saisissez le sujet ou la leçon à préparer. Le rapport concevra les objectifs, la progression, les activités et l’évaluation à partir de vos ressources.',
  'Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.': 'Saisissez le sujet des notes. Le rapport l’expliquera pas à pas avec des exemples et une autoévaluation fondés sur vos ressources.',
  'Público objetivo y producto': 'Public cible et livrable',
  'Docente · planificación de la lección': 'Enseignant · plan de leçon',
  'Alumnado · apuntes para entregar': 'Élèves · notes à distribuer',
  'Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.': 'Le rapport produira des objectifs, une progression, des activités, des vérifications de compréhension et une évaluation pour l’enseignant.',
  'Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.': 'Le rapport produira pour les élèves des explications, des définitions, des exemples, des synthèses et une autoévaluation.',
  'En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.': 'Dans « Créer », les unités pédagogiques permettent désormais de produire un plan pour l’enseignant ou des notes pour les élèves à partir de vos ressources. Les autres sections en pointillés restent ouvertes à vos suggestions. Vous pouvez relancer ce tutoriel depuis les paramètres.',
