  'Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.': 'Les articles servent à ce qui n’est ni un personnage, ni un lieu, ni une faction : la magie, une religion, une langue, une créature, un objet. Tout le reste figure déjà dans l’encyclopédie.',
