  'reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos': 'règles du monde, conflits, arcs narratifs, cohérence, questions ouvertes, intrigues et manuscrits',
  'En la enciclopedia': 'Dans l’encyclopédie',
  '{count} sin desarrollar': '{count} à développer',
  'Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].': 'Construisez un monde de fiction pièce à pièce : personnages, lieux, factions, cultures, scènes et cartes. L’encyclopédie les réunit dans un seul index et vous laisse écrire le reste du monde — la magie, une religion, une langue — en le liant avec [[doubles crochets]].',
  'Analizar el mundo': 'Analyser le monde',
  'Aparecen a menudo y no están definidos': 'Ils reviennent souvent et ne sont pas définis',
