  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium efface les cookies par domaine enregistrable : effacer ceux d'un sous-domaine efface aussi ceux du domaine principal et de ses autres sous-domaines.",
